import { runAstGate } from './gates/astGate.js';
import { runFlakeGate } from './gates/flakeGate.js';
import { runMutationGate } from './gates/mutationGate.js';
import { computeGrade } from './grade.js';
import { resolveGitScope } from './gitScope.js';
import type {
  DiffEntry,
  FireguardConfig,
  FireguardReport,
  RunOnceResult,
  TestRunner,
} from './types.js';

export interface RunFireguardDeps {
  config: FireguardConfig;
  getDiffEntries: () => Promise<DiffEntry[]>;
  readFile: (path: string) => Promise<string>;
  runOnce: TestRunner;
  applyAndTest: (input: {
    file: string;
    originalSource: string;
    mutatedSource: string;
    relatedTests: string[];
  }) => Promise<RunOnceResult>;
}

export async function runFireguard(deps: RunFireguardDeps): Promise<FireguardReport> {
  const entries = await deps.getDiffEntries();
  const scope = resolveGitScope({ config: deps.config, entries });

  const scopePayload = {
    baseRef: deps.config.baseRef,
    gradedTestFiles: scope.gradedTestFiles,
    changedModules: scope.changedModules,
  };

  // Fail closed: production module changes without graded test updates cannot earn a free A.
  if (scope.gradedTestFiles.length === 0 && scope.changedModules.length > 0) {
    return {
      grade: {
        letter: 'F',
        score: 0,
        reasons: ['production modules changed without graded unit test updates'],
      },
      gates: {},
      scope: scopePayload,
      skipped: false,
      skipReason: undefined,
    };
  }

  if (scope.gradedTestFiles.length === 0) {
    return {
      grade: {
        letter: 'A',
        score: 100,
        reasons: ['no graded unit tests to evaluate'],
      },
      gates: {},
      scope: scopePayload,
      skipped: true,
      skipReason: 'No added/modified unit tests vs base ref',
    };
  }

  const gates: FireguardReport['gates'] = {};

  const files = await Promise.all(
    scope.gradedTestFiles.map(async (path) => ({
      path,
      source: await deps.readFile(path),
    }))
  );
  gates.ast = runAstGate({ config: deps.config, files });
  if (!gates.ast.pass) {
    return {
      grade: computeGrade(gates),
      gates,
      scope: scopePayload,
      skipped: false,
    };
  }

  gates.flake = await runFlakeGate({
    config: deps.config,
    files: scope.gradedTestFiles,
    runOnce: deps.runOnce,
  });
  if (!gates.flake.pass) {
    return {
      grade: computeGrade(gates),
      gates,
      scope: scopePayload,
      skipped: false,
    };
  }

  if (scope.changedModules.length > 0) {
    const modules = await Promise.all(
      scope.changedModules.map(async (path) => ({
        path,
        source: await deps.readFile(path),
      }))
    );
    gates.mutation = await runMutationGate({
      config: deps.config,
      modules,
      relatedTests: scope.gradedTestFiles,
      applyAndTest: deps.applyAndTest,
    });
  }

  return {
    grade: computeGrade(gates),
    gates,
    scope: scopePayload,
    skipped: false,
  };
}

fireguard/src/types.ts:
export type LetterGrade = 'A' | 'B' | 'C' | 'D' | 'F';

export interface FireguardThresholds {
  maxMockToAssertRatio: number;
  maxTautologicalRatio: number;
  minAssertionsPerFile: number;
  minMutationScore: number;
  flakinessRuns: number;
  agenticFlakinessRuns: number;
  maxFlakeRate: number;
}

export interface FireguardConfig {
  thresholds: FireguardThresholds;
  include: string[];
  exclude: string[];
  baseRef: string;
  testCommand: string;
}

export interface AstFinding {
  file: string;
  line: number;
  rule: string;
  message: string;
}

export interface AstGateResult {
  name: 'ast';
  pass: boolean;
  assertionCount: number;
  mockCount: number;
  mockToAssertRatio: number;
  tautologicalCount: number;
  tautologicalRatio: number;
  emptyTests: Array<{ file: string; line: number; name: string }>;
  findings: AstFinding[];
}

export interface FlakeGateResult {
  name: 'flake';
  pass: boolean;
  /** How many runs were actually executed (may be < configuredRuns on fail-fast). */
  runs: number;
  /** Configured agentic flake run budget. */
  configuredRuns: number;
  failures: number;
  flakeRate: number;
  files: string[];
  failedRuns: Array<{ run: number; error: string }>;
  failFast: boolean;
}

export interface MutationSurvivor {
  file: string;
  line: number;
  description: string;
}

export interface MutationGateResult {
  name: 'mutation';
  pass: boolean;
  killed: number;
  survived: number;
  total: number;
  score: number;
  survivors: MutationSurvivor[];
  modules: string[];
}

export type GateResult = AstGateResult | FlakeGateResult | MutationGateResult;

export interface GradeResult {
  letter: LetterGrade;
  score: number;
  reasons: string[];
}

export interface FireguardReport {
  grade: GradeResult;
  gates: {
    ast?: AstGateResult;
    flake?: FlakeGateResult;
    mutation?: MutationGateResult;
  };
  scope: {
    baseRef: string;
    /** Added or modified unit test files in scope for grading. */
    gradedTestFiles: string[];
    changedModules: string[];
  };
  skipped: boolean;
  skipReason?: string;
}

export interface GitScope {
  /** Added or modified unit test files matching include globs. */
  gradedTestFiles: string[];
  changedModules: string[];
}

export type DiffStatus = 'A' | 'M' | 'D' | 'R' | 'C' | 'T' | 'U' | '?';

export interface DiffEntry {
  status: DiffStatus;
  path: string;
  /** For renames, the new path is `path`; old may be provided. */
  oldPath?: string;
}

export interface RunOnceResult {
  ok: boolean;
  error?: string;
}

export type TestRunner = (files: string[]) => Promise<RunOnceResult>;

