scripts/assert-dist-index.mjs:
/**
 * CLI guard for dist/index.html (and optional live-site HTML via argv).
 * Keep regexes in sync with src/deploy/assertProductionHtml.ts
 */
import { readFileSync } from 'node:fs';

export function isProductionIndexHtml(html) {
  const hasDevEntry = /src=["']\/src\/main\.tsx["']/.test(html);
  const hasHashedAsset =
    /src=["'][^"']*\/assets\/[^"']+\.(js|mjs)["']/.test(html) ||
    /href=["'][^"']*\/assets\/[^"']+\.css["']/.test(html);
  return !hasDevEntry && hasHashedAsset;
}

const label = process.argv[2] ?? 'dist/index.html';
const html =
  label.startsWith('http://') || label.startsWith('https://')
    ? await (await fetch(label)).text()
    : readFileSync(label, 'utf8');

if (!isProductionIndexHtml(html)) {
  console.error(`${label} looks like a Vite dev entry (or is missing hashed /assets bundles).`);
  console.error(
    'GitHub Pages must serve the Vite dist/ build via Actions, not the repo-root source.'
  );
  console.error('Check Settings → Pages → Source = GitHub Actions.');
  process.exit(1);
}

console.log(`OK: ${label} looks like a production Vite build`);

scripts/bump-minor-version.mjs:
import { readFileSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

/**
 * Bumps package.json minor version (x.Y.0) and syncs package-lock.json.
 * Prints the new version to stdout for CI.
 */
export function bumpMinorVersion(pkgPath = 'package.json', lockPath = 'package-lock.json') {
  const pkg = JSON.parse(readFileSync(pkgPath, 'utf8'));
  const parts = String(pkg.version)
    .split('.')
    .map((part) => Number.parseInt(part, 10));
  if (parts.length !== 3 || parts.some((part) => Number.isNaN(part))) {
    throw new Error(`Invalid semver in ${pkgPath}: ${pkg.version}`);
  }
  const [major, minor] = parts;
  const nextVersion = `${major}.${minor + 1}.0`;
  pkg.version = nextVersion;
  writeFileSync(pkgPath, `${JSON.stringify(pkg, null, 2)}\n`);

  try {
    const lock = JSON.parse(readFileSync(lockPath, 'utf8'));
    lock.version = nextVersion;
    if (lock.packages?.['']) {
      lock.packages[''].version = nextVersion;
    }
    writeFileSync(lockPath, `${JSON.stringify(lock, null, 2)}\n`);
  } catch {
    // package-lock may be absent in some environments
  }

  return nextVersion;
}

const isCli =
  typeof process.argv[1] === 'string' && import.meta.url === pathToFileURL(process.argv[1]).href;

if (isCli) {
  process.stdout.write(bumpMinorVersion());
}

