/// <reference types="vitest" />
import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import { writeFileSync } from 'fs';
import { resolve } from 'path';

const basePath = process.env.BASE || process.env.VITE_BASE || '/';

export default defineConfig({
  plugins: [
    react(),
    {
      name: 'create-nojekyll',
      closeBundle() {
        const outDir = resolve(__dirname, 'dist');
        writeFileSync(resolve(outDir, '.nojekyll'), '');
      },
    },
  ],
  base: basePath,
  build: {
    outDir: 'dist',
  },
  test: {
    globals: true,
    environment: 'jsdom',
    setupFiles: ['./src/test/setup.ts'],
    include: ['src/**/*.{test,spec}.{ts,tsx}', 'scripts/**/*.test.mjs'],
    environmentMatchGlobs: [['scripts/**', 'node']],
  },
});

import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = new URL('../', import.meta.url);
const starter = new URL('templates/electron/starter/', root);
const files = {
  'main.ts': 'src/electron/main.ts',
  'preload.ts': 'src/electron/preload.ts',
  'renderer.tsx': 'src/electron-renderer.tsx',
  'electron.html': 'electron.html',
  'electron.vite.config.ts': 'electron.vite.config.ts',
};

const packageFile = new URL('package.json', root);
const pkg = JSON.parse(await readFile(packageFile, 'utf8'));
if (!pkg.dependencies?.react || !pkg.devDependencies?.vite) {
  throw new Error('This conversion expects the BoosterSeat React/Vite starter.');
}

const planned = await Promise.all(Object.entries(files).map(async ([template, path]) => {
  const body = await readFile(new URL(template, starter));
  const target = new URL(path, root);
  const existing = await readFile(target).catch(error => {
    if (error.code !== 'ENOENT') throw error;
    return null;
  });
  if (existing !== null && !body.equals(existing)) throw new Error('A different file already exists: ' + path);
  return { target, body, exists: existing !== null };
}));

const main = 'out/main/index.cjs';
const scripts = { 'desktop:dev': 'electron-vite dev', 'desktop:build': 'tsc --noEmit && electron-vite build', 'desktop:start': 'electron .' };
const deps = { electron: '42.11.18', 'electron-vite': '5.0.0' };
if ((pkg.main !== undefined && pkg.main !== main) ||
    Object.entries(scripts).some(([key, value]) => pkg.scripts?.[key] !== undefined && pkg.scripts[key] !== value) ||
    Object.entries(deps).some(([key, value]) => pkg.dependencies?.[key] !== undefined ||
      (pkg.devDependencies?.[key] !== undefined && pkg.devDependencies[key] !== value))) {
  throw new Error('Review existing Electron entrypoints, scripts or versions before converting.');
}

for (const { target, body, exists } of planned) {
  if (exists) continue;
  await mkdir(dirname(fileURLToPath(target)), { recursive: true });
  await writeFile(target, body, { flag: 'wx' });
}
pkg.main = main;
pkg.scripts = { ...pkg.scripts, ...scripts };
pkg.devDependencies = { ...pkg.devDependencies, ...deps };
await writeFile(packageFile, JSON.stringify(pkg, null, 2) + '\n');
console.log('Electron source configured. Run npm install, npm run desktop:build and npm run desktop:start to verify it.');

